    private boolean isSuccess = false;

    private LocalDateTime paymentDate;

    @Enumerated(EnumType.STRING)
    private Xbf54Status status = Xbf54Status.PENDING;


    public void assignOrder(Xdg64 order) {
        this.order = order;
        this.sale = null;
    }

